"""
test_prompt_dataset_split.py
============================
Split integrity of the Stage-1 prompt-injection dataset (prompt_injection_gate/training/
dataset_schema.md): nothing a model is tuned or reported on may have been seen in training.

  * the committed cloud slice (prompt_injection_cloud.jsonl / .csv) -- train/test, grouped on
    template_id -- and the DEV slice the training harness carves out of train
    (train_eval_baseline.dev_split: 20% of train TEMPLATES, seed 7);
  * the merged public set (prompt_injection_merged.jsonl) is gitignored and regenerated by
    merge_public.py; its checks skip when it is absent.

Checked across every pair of train / dev / test: no exact duplicate and no near-duplicate prompt
(normalised lowercase / whitespace / punctuation; token Jaccard >= 0.9 or difflib ratio >= 0.9),
no template_id in two splits; and that the reported model run tuned on dev and reported on test.
"""

import difflib
import hashlib
import importlib.util
import json
import os
import re
import string
import sys
import unittest
from collections import Counter

import pandas as pd

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PI = os.path.join(ROOT, "datasets", "prompt-injection")
CLOUD_JSONL = os.path.join(PI, "prompt_injection_cloud.jsonl")
CLOUD_CSV = os.path.join(PI, "prompt_injection_cloud.csv")
MERGED = os.path.join(PI, "prompt_injection_merged.jsonl")
HARNESS = os.path.join(PI, "train_eval_baseline.py")
with open(os.path.join(ROOT, "prompt_injection_gate", "checkpoint.json"), encoding="utf-8") as _f:
    RESULTS = os.path.join(ROOT, "prompt_injection_gate", json.load(_f)["results"])   # the shipped checkpoint
TRAINER = os.path.join(ROOT, "prompt_injection_gate", "training", "train_eval_transformer.py")
NEAR = 0.9
_PUNCT = re.compile("[%s]" % re.escape(string.punctuation))


def load_harness():
    """Imported the way train_eval_transformer.py imports it: by path, not edited."""
    spec = importlib.util.spec_from_file_location("pi_harness_under_test", HARNESS)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def read_jsonl(path):
    with open(path, encoding="utf-8") as f:
        return [json.loads(l) for l in f if l.strip()]


def norm(text):
    return " ".join(_PUNCT.sub(" ", text.lower()).split())


def splits_of(rows, H):
    train = [r for r in rows if r["split"] in ("train", "public_train")]
    test = [r for r in rows if r["split"] in ("test", "public_test")]
    tr, dev = H.dev_split(train)
    return {"train": tr, "dev": dev, "test": test}


def duplicates(a_rows, b_rows):
    """(#exact, #near, worst examples) of b rows that have an (near-)identical row in a."""
    a = [(norm(r["text"]), set(norm(r["text"]).split()), r) for r in a_rows]
    exact_set = {n for n, _, _ in a}
    exact = near = 0
    worst = (0.0, None, None)
    for r in b_rows:
        nb = norm(r["text"])
        tb = set(nb.split())
        if nb in exact_set:
            exact += 1
            continue
        hit = False
        for na, ta, ra in a:
            jac = len(ta & tb) / len(ta | tb) if (ta or tb) else 1.0
            sm = difflib.SequenceMatcher(None, na, nb, autojunk=False)
            ratio = sm.ratio() if sm.real_quick_ratio() >= NEAR and sm.quick_ratio() >= NEAR else 0.0
            score = max(jac, ratio)
            if score > worst[0]:
                worst = (round(score, 3), ra["text"][:80], r["text"][:80])
            if score >= NEAR:
                hit = True
                break
        near += hit
    return exact, near, worst


class _SplitChecks:
    """Mixed into a TestCase that sets cls.rows / cls.splits."""

    def test_split_labels_are_the_documented_ones(self):
        self.assertTrue(set(r["split"] for r in self.rows) <= {"train", "test", "public_train", "public_test"})
        for name, rows in self.splits.items():
            self.assertTrue(rows, f"empty {name} split")

    def test_ids_are_unique_and_never_in_two_splits(self):
        ids = Counter(r["id"] for r in self.rows)
        self.assertEqual([i for i, n in ids.items() if n > 1], [])
        seen = {}
        for name, rows in self.splits.items():
            for r in rows:
                self.assertNotIn(r["id"], seen, f"{r['id']} in {seen.get(r['id'])} and {name}")
                seen[r["id"]] = name

    def test_templates_do_not_cross_splits(self):
        tmpl = {name: {r["template_id"] for r in rows} for name, rows in self.splits.items()}
        for a, b in (("train", "test"), ("dev", "test"), ("train", "dev")):
            self.assertEqual(tmpl[a] & tmpl[b], set(), f"template_id shared by {a} and {b}")

    def test_dev_is_carved_from_train_only_and_deterministically(self):
        train_ids = {r["id"] for r in self.rows if r["split"] in ("train", "public_train")}
        self.assertTrue({r["id"] for r in self.splits["dev"]} <= train_ids)
        again = splits_of(self.rows, self.H)
        self.assertEqual([r["id"] for r in again["dev"]], [r["id"] for r in self.splits["dev"]])

    def _pair(self, a, b):
        exact, near, worst = duplicates(self.splits[a], self.splits[b])
        self.__class__.dup_report[f"{a}->{b}"] = {"exact": exact, "near": near, "max_similarity": worst[0],
                                                  "closest_pair": worst[1:]}
        print(f"\n[SPLIT] {self.label} {a} vs {b}: exact {exact}, near (>= {NEAR}) {near} of {len(self.splits[b])}; "
              f"max similarity {worst[0]}", file=sys.stderr)
        self.assertEqual((exact, near), (0, 0), f"{a} vs {b}: closest {worst}")

    def test_no_duplicate_train_vs_test(self):
        self._pair("train", "test")

    def test_no_duplicate_dev_vs_test(self):
        self._pair("dev", "test")

    def test_no_duplicate_train_vs_dev(self):
        self._pair("train", "dev")


class CloudSliceSplitTests(_SplitChecks, unittest.TestCase):
    label = "cloud slice"
    dup_report = {}

    @classmethod
    def setUpClass(cls):
        if not os.path.exists(CLOUD_JSONL):
            raise unittest.SkipTest(f"{CLOUD_JSONL} not present")
        cls.H = load_harness()
        cls.rows = read_jsonl(CLOUD_JSONL)
        cls.splits = splits_of(cls.rows, cls.H)
        print(f"\n[SPLIT] cloud slice: {len(cls.rows)} rows, "
              + ", ".join(f"{k} {len(v)} rows / {len({r['template_id'] for r in v})} templates"
                          for k, v in cls.splits.items()), file=sys.stderr)

    def test_row_id_is_the_sha1_of_the_text(self):
        for r in self.rows:
            self.assertEqual(r["id"], hashlib.sha1(r["text"].encode("utf-8")).hexdigest())

    def test_csv_and_jsonl_copies_agree(self):
        # The committed CSV blob is LF-only. A Windows checkout with core.autocrlf=true (no
        # .gitattributes rule for *.csv) rewrites the newlines INSIDE quoted text fields to CRLF, so
        # line endings are normalised here; any other difference is a real mismatch.
        csv = pd.read_csv(CLOUD_CSV, keep_default_na=False).set_index("id")
        self.assertEqual(set(csv.index), {r["id"] for r in self.rows})
        for r in self.rows:
            row = csv.loc[r["id"]]
            self.assertEqual((row["split"], row["template_id"], row["text"].replace("\r\n", "\n")),
                             (r["split"], r["template_id"], r["text"]))

    def test_slice_is_cloud_specific_team_synthetic(self):
        self.assertEqual({r["source"] for r in self.rows}, {"team_synthetic"})
        self.assertTrue(all(r["cloud_specific"] for r in self.rows))


class MergedDatasetSplitTests(_SplitChecks, unittest.TestCase):
    label = "merged public+cloud"
    dup_report = {}

    @classmethod
    def setUpClass(cls):
        if not os.path.exists(MERGED):
            raise unittest.SkipTest("prompt_injection_merged.jsonl is gitignored (datasets/prompt-injection/"
                                    ".gitignore) and not present; regenerate with merge_public.py to check it")
        cls.H = load_harness()
        cls.rows = read_jsonl(MERGED)
        cls.splits = splits_of(cls.rows, cls.H)


class TuneOnDevReportOnTestTests(unittest.TestCase):
    """The reported checkpoint chose its epoch and thresholds on dev and only reported on test."""

    @classmethod
    def setUpClass(cls):
        if not os.path.exists(RESULTS):
            raise unittest.SkipTest(f"{RESULTS} not present")
        with open(RESULTS, encoding="utf-8") as f:
            cls.res = json.load(f)

    def test_the_run_used_the_committed_harness(self):
        with open(HARNESS, "rb") as f:
            self.assertEqual(self.res["harness_sha256"], hashlib.sha256(f.read()).hexdigest())

    def test_selection_and_thresholds_come_from_dev(self):
        self.assertGreater(self.res["n_dev"], 0)
        self.assertTrue(all("dev_attack_auc" in e for e in self.res["epoch_history"]))
        best = max(self.res["epoch_history"], key=lambda e: e["dev_attack_auc"])
        self.assertEqual(self.res["selected_epoch"], best["epoch"])
        rules = self.res["gate_model"].get("threshold_rule") or self.res.get("threshold_rule") or {}
        text = json.dumps(rules).lower()
        self.assertIn("dev", text)
        self.assertNotIn("test", text)

    def test_reported_sets_are_test_splits_only(self):
        held = self.res["held_out"]
        self.assertTrue(held)
        for name in held:
            self.assertTrue(name == "cloud_test" or name.startswith("public_test:"), name)
        n_cloud_test = sum(r["split"] == "test" for r in read_jsonl(CLOUD_JSONL))
        self.assertEqual(held["cloud_test"]["n"], n_cloud_test)

    def test_trainer_freezes_thresholds_before_touching_test(self):
        with open(TRAINER, encoding="utf-8") as f:
            src = f.read()
        first_test_use = src.index("for name, rs in test_sets.items()")
        for marker in ("thr = next(", "safe_thr =", "cat_thr[c] ="):
            self.assertLess(src.index(marker), first_test_use, marker)
        self.assertNotIn("test_sets", src[src.index("for ep in"):src.index("safe_thr =")])


if __name__ == "__main__":
    unittest.main()
